const input = $input.first().json;
const b = input.body || input;
const prompt = String(b.prompt ?? '').trim().slice(0, 10000);
if (!prompt) {
  throw new Error('El campo prompt es obligatorio');
}

// Normalizar leetspeak básico para detectar evasión polimórfica
const deobfuscated = prompt
  .toLowerCase()
  .replace(/0/g, 'o')
  .replace(/1/g, 'i')
  .replace(/3/g, 'e')
  .replace(/4/g, 'a')
  .replace(/5/g, 's')
  .replace(/7/g, 't')
  .replace(/[_.-]/g, '');

const heuristic_attack = /(ignore\s+(all\s+)?previous|system:|modo\s+desarrollador|developer\s+mode|bypass|jailbreak|\|\s*---\s*\|)/i.test(deobfuscated);

const session_id = String(b.session_id || ('anon-' + Date.now())).slice(0, 100);
const discord = (b.discord && b.discord.channel_id)
  ? {
      channel_id: String(b.discord.channel_id),
      message_id: b.discord.message_id ? String(b.discord.message_id) : undefined
    }
  : null;

return [{ json: { session_id, prompt, discord, heuristic_attack, started_at: Date.now() } }];

