const n = $('Normalizar').first().json;
const out = $input.first().json;
let raw = (out.message && out.message.content) ? String(out.message.content) : '';
raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');

let g = null;
try {
  g = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) {
    try { g = JSON.parse(m[0]); } catch (e2) { g = null; }
  }
}

const parsed = g !== null && typeof g === 'object' && !Array.isArray(g);
const valid = ['low', 'medium', 'high'];
let threat_level = parsed && valid.includes(g.threat_level) ? g.threat_level : 'high';
let risk_category = (parsed && typeof g.risk_category === 'string' && g.risk_category.trim())
  ? g.risk_category.trim()
  : (parsed ? 'none' : 'parse_error');

let explanation = '';
if (parsed && g.explanation) {
  explanation = typeof g.explanation === 'string' ? g.explanation : JSON.stringify(g.explanation);
} else {
  explanation = 'El Guardian no devolvio JSON valido; se aplica politica fail-closed.';
}

// Si la heurística detectó inyección polimórfica o delimitadores, escalar a high
if (n.heuristic_attack && threat_level === 'low') {
  threat_level = 'high';
  risk_category = 'polymorphic_or_delimiter_injection';
  explanation = 'Bloqueado por detección de evasión polimórfica o delimitadores de sistema.';
}

const should_block = !parsed || g.should_block === true || threat_level === 'high' || n.heuristic_attack;

return [{ json: {
  ...n,
  threat_level,
  risk_category,
  explanation,
  should_block,
  parse_error: !parsed,
  guardian_model: out.model || 'phi3:mini'
} }];

