const c = $('Construir contexto').first().json;
const a = $input.first().json;

let answer = '';
if (c.num_chunks === 0) {
  answer = 'No dispongo de información en el corpus de seguridad en LLMs para responder a esa consulta.';
} else {
  answer = (a.message && a.message.content) ? a.message.content : '';
  const sin_info = /no dispongo de informaci[oó]n/i.test(answer);
  const files = [...new Set((c.sources || []).map(s => s && s.source).filter(Boolean))];
  if (!sin_info && files.length > 0 && !/fuentes/i.test(answer)) {
    answer += '\n\nFuentes: ' + files.join(', ');
  }
}

return [{ json: {
  session_id: c.session_id,
  prompt: c.prompt,
  discord: c.discord,
  answer,
  blocked: false,
  threat_level: c.threat_level,
  risk_category: c.risk_category,
  parse_error: c.parse_error === true,
  sources: c.sources,
  model: c.num_chunks === 0 ? 'rag-threshold-bypass' : (a.model || 'phi3:mini'),
  latency_ms: Date.now() - c.started_at
} }];

