const resp = $('Formatear respuesta').first().json;
if (!resp.discord || !resp.discord.channel_id) {
  return [];
}

const answer = resp.answer || 'Sin respuesta del sistema.';
const MAX_LEN = 1900;
const chunks = [];
for (let i = 0; i < answer.length; i += MAX_LEN) {
  chunks.push(answer.slice(i, i + MAX_LEN));
}

return chunks.map((chunk, idx) => ({
  json: {
    channel_id: resp.discord.channel_id,
    content: chunk,
    message_reference: idx === 0 ? resp.discord.message_id : undefined
  }
}));

const out = [];
const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const binary = item.binary || {};
  const keys = Object.keys(binary);

  if (keys.length === 0) {
    out.push(item);
    continue;
  }

  for (const key of keys) {
    const meta = binary[key];
    const fallback = item.json && item.json.data && item.json.data[0] && item.json.data[0].filename;
    out.push({
      json: { ...item.json, source: meta.fileName || fallback || ('archivo-' + i) },
      binary: { data: meta },
      pairedItem: item.pairedItem || { item: i }
    });
  }
}

return out;
